const tz = 'Europe/Zurich';
const now = new Date();
const dateKey = now.toLocaleDateString('en-CA', { timeZone: tz });
const dayIndex = Math.floor(Date.parse(dateKey + 'T00:00:00Z') / 86400000);
const topics = [
  { key: 'website-leads', title: 'Wie eine KMU-Website automatisch qualifizierte Anfragen gewinnt', angle: 'Konkreter Vorher-Nachher-Ablauf vom Formular bis zum Rückruf' },
  { key: 'kundenportal', title: 'Kundenportal statt E-Mail-Chaos', angle: 'Status, Dokumente und Freigaben an einem Ort' },
  { key: 'offerten', title: 'Offerten automatisch vorbereiten', angle: 'Anfrage strukturieren, Daten prüfen und Entwurf erzeugen' },
  { key: 'terminworkflow', title: 'Termine ohne Hin und Her koordinieren', angle: 'Formular, Kalenderprüfung und automatische Bestätigung' },
  { key: 'ki-support', title: 'KI beantwortet wiederkehrende Kundenfragen', angle: 'Wissensbasis mit sauberer Übergabe an einen Menschen' },
  { key: 'mobile-webapp', title: 'Interne Abläufe als mobile Web-App', angle: 'Checklisten, Fotos und Status direkt vor Ort erfassen' },
  { key: 'datenfluss', title: 'Doppelte Dateneingabe eliminieren', angle: 'Website, CRM und Buchhaltung zuverlässig verbinden' },
  { key: 'website-speed', title: 'Langsame Website kostet Anfragen', angle: 'Drei messbare Verbesserungen für Schweizer KMU' }
];
const topic = topics[((dayIndex % topics.length) + topics.length) % topics.length];
const isManual = $execution.mode === 'manual';
const runStamp = now.toLocaleString('sv-SE', { timeZone: tz }).replace(/[^0-9]/g, '').slice(0, 12);
const postKey = isManual ? `test-${dateKey}-${topic.key}-${runStamp}` : `${dateKey}-${topic.key}`;
return [{ json: {
  postKey,
  dateKey,
  timezone: tz,
  mode: isManual ? 'controlled-test' : 'scheduled',
  topic: topic.title,
  angle: topic.angle,
  brand: {
    name: 'FlowerTech',
    domain: 'https://flowertech.ch',
    audience: 'Schweizer KMU und Privatpersonen',
    colors: ['#081d17', '#c8f36b', '#f5f1e8'],
    style: 'ruhig, hochwertig, technisch klar, keine erfundenen Kunden oder Zahlen'
  }
} }];

