const run = $('Lauf & Thema vorbereiten').first().json;
const raw = $json?.choices?.[0]?.message?.content;
if (!raw) throw new Error('OpenAI lieferte keinen Inhalt.');
let concept;
try { concept = JSON.parse(raw); } catch { throw new Error('OpenAI-Antwort ist kein valides JSON.'); }
if (!concept.hook || !concept.caption || !concept.cta || !concept.videoPrompt || !Array.isArray(concept.scenes) || concept.scenes.length !== 5) {
  throw new Error('Reel-Konzept ist unvollständig.');
}
return [{ json: { ...run, ...concept, status: 'generating' } }];

const concept = $('Konzept validieren').first().json;
const videoUrl = $json.video_url || $json.videoUrl || $json.url || $json.output?.url || $json.data?.url;
if (!videoUrl || !String(videoUrl).startsWith('https://')) throw new Error('Der Videoanbieter lieferte keine öffentliche HTTPS-Video-URL.');
return [{ json: { ...concept, videoUrl: String(videoUrl), providerJobId: $json.id || $json.job_id || $json.data?.id || null, status: 'ready' } }];
